-- Create "customers" table
CREATE TABLE "customers" ("id" character varying(40) NOT NULL, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "name" character varying(200) NOT NULL, "email" character varying(320) NULL, "external_refs" jsonb NOT NULL, "archived_at" timestamptz NULL, "tenant_id" character varying(40) NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "customers_tenants_customers" FOREIGN KEY ("tenant_id") REFERENCES "tenants" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "customers_email_format" CHECK ((email IS NULL) OR ((email)::text ~ '^[^@[:space:]]+@[^@[:space:]]+$'::text)), CONSTRAINT "customers_id_format" CHECK ((id)::text ~ '^cus_[a-z2-7]{26}$'::text), CONSTRAINT "customers_name_not_blank" CHECK (btrim((name)::text) <> ''::text), CONSTRAINT "customers_refs_strings" CHECK ((jsonb_typeof(external_refs) = 'object'::text) AND (NOT jsonb_path_exists(external_refs, 'strict $.*?(@.type() != "string")'::jsonpath))));
-- Create index "customer_tenant_id" to table: "customers"
CREATE INDEX "customer_tenant_id" ON "customers" ("tenant_id");
-- Create index "customer_tenant_id_id" to table: "customers"
