-- Modify "plans" table
ALTER TABLE "plans" ADD CONSTRAINT "plans_bind_type_valid" CHECK ((bind_type)::text = ANY (ARRAY['none'::text, 'machine'::text, 'cluster'::text])), ADD COLUMN "bind_type" character varying NOT NULL DEFAULT 'machine';
-- Create index "plan_tenant_id_product_id_id_slug" to table: "plans"
