-- Create "licenses" table
CREATE TABLE "licenses" ("id" character varying(40) NOT NULL, "tenant_id" character varying(40) NOT NULL, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "type" character varying NOT NULL DEFAULT 'paid', "status" character varying NOT NULL DEFAULT 'active', "key_ciphertext" character varying(200) NOT NULL, "key_lookup" character varying(64) NOT NULL, "key_hint" character varying(6) NOT NULL, "plan_slug" character varying(63) NOT NULL, "expiry_basis" character varying NOT NULL, "duration_months" bigint NULL, "duration_seconds" bigint NULL, "max_activations" bigint NULL, "max_rehosts" bigint NULL, "bind_type" character varying NOT NULL, "offline_allowed" boolean NOT NULL, "lease_seconds" bigint NOT NULL, "max_offline_seconds" bigint NULL, "grace_seconds" bigint NOT NULL, "entitlements" jsonb NOT NULL, "issued_at" timestamptz NOT NULL, "expires_at" timestamptz NULL, "first_activated_at" timestamptz NULL, "updates_until" timestamptz NULL, "suspended_at" timestamptz NULL, "revoked_at" timestamptz NULL, "rehost_count" bigint NOT NULL DEFAULT 0, "external_refs" jsonb NOT NULL, "customer_id" character varying(40) NOT NULL, "plan_id" character varying(40) NOT NULL, "product_id" character varying(40) NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "licenses_customers_licenses" FOREIGN KEY ("customer_id") REFERENCES "customers" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "licenses_plans_licenses" FOREIGN KEY ("plan_id") REFERENCES "plans" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "licenses_products_licenses" FOREIGN KEY ("product_id") REFERENCES "products" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "licenses_activated_after_issue" CHECK ((first_activated_at IS NULL) OR (first_activated_at >= issued_at)), CONSTRAINT "licenses_activations_rng" CHECK ((max_activations IS NULL) OR ((max_activations >= 1) AND (max_activations <= 1000000))), CONSTRAINT "licenses_bind_valid" CHECK ((bind_type)::text = ANY (ARRAY['none'::text, 'machine'::text, 'cluster'::text])), CONSTRAINT "licenses_duration_months" CHECK ((duration_months IS NULL) OR ((duration_months >= 1) AND (duration_months <= 1200))), CONSTRAINT "licenses_duration_secs" CHECK ((duration_seconds IS NULL) OR ((duration_seconds >= 1) AND (duration_seconds <= '3153600000'::bigint))), CONSTRAINT "licenses_ent_features" CHECK (NOT jsonb_path_exists(entitlements, 'strict $."features"[*]?(@.type() != "string" || !(@ like_regex "^[a-z][a-z0-9]*(_[a-z0-9]+)*$"))'::jsonpath)), CONSTRAINT "licenses_ent_limits" CHECK (NOT jsonb_path_exists(entitlements, 'strict $."limits".*?(((@.type() != "number" || @ < -1) || @ > 9007199254740991) || @ != @.floor())'::jsonpath)), CONSTRAINT "licenses_entitlements" CHECK ((jsonb_typeof(entitlements) = 'object'::text) AND (jsonb_typeof((entitlements -> 'features'::text)) = 'array'::text) AND (jsonb_typeof((entitlements -> 'limits'::text)) = 'object'::text)), CONSTRAINT "licenses_expiry_after_issue" CHECK ((expires_at IS NULL) OR (expires_at > issued_at)), CONSTRAINT "licenses_expiry_valid" CHECK ((expiry_basis)::text = ANY (ARRAY['from_issue'::text, 'from_first_activation'::text])), CONSTRAINT "licenses_grace_range" CHECK ((grace_seconds >= 0) AND (grace_seconds <= '3153600000'::bigint)), CONSTRAINT "licenses_id_format" CHECK ((id)::text ~ '^lic_[a-z2-7]{26}$'::text), CONSTRAINT "licenses_key_ciphertext" CHECK ((key_ciphertext)::text ~ '^v1\.[a-z0-9-]{1,32}\.[A-Za-z0-9_-]{60,}$'::text), CONSTRAINT "licenses_key_hint" CHECK ((key_hint)::text ~ '^[A-Z2-7]{6}$'::text), CONSTRAINT "licenses_key_lookup" CHECK ((key_lookup)::text ~ '^[0-9a-f]{64}$'::text), CONSTRAINT "licenses_lease_range" CHECK ((lease_seconds >= 1) AND (lease_seconds <= '3153600000'::bigint)), CONSTRAINT "licenses_max_offline_rng" CHECK ((max_offline_seconds IS NULL) OR ((max_offline_seconds >= 0) AND (max_offline_seconds <= '3153600000'::bigint))), CONSTRAINT "licenses_one_duration" CHECK (num_nonnulls(duration_months, duration_seconds) <= 1), CONSTRAINT "licenses_perpetual_no_expiry" CHECK ((num_nonnulls(duration_months, duration_seconds) > 0) OR (expires_at IS NULL)), CONSTRAINT "licenses_plan_slug" CHECK ((plan_slug)::text ~ '^[a-z][a-z0-9]*(-[a-z0-9]+)*$'::text), CONSTRAINT "licenses_refs_strings" CHECK ((jsonb_typeof(external_refs) = 'object'::text) AND (NOT jsonb_path_exists(external_refs, 'strict $.*?(@.type() != "string")'::jsonpath))), CONSTRAINT "licenses_rehosts_nonneg" CHECK (rehost_count >= 0), CONSTRAINT "licenses_rehosts_rng" CHECK ((max_rehosts IS NULL) OR ((max_rehosts >= 0) AND (max_rehosts <= 1000000))), CONSTRAINT "licenses_rehosts_within_limit" CHECK ((max_rehosts IS NULL) OR (rehost_count <= max_rehosts)), CONSTRAINT "licenses_revoked_at" CHECK (((status)::text = 'revoked'::text) = (revoked_at IS NOT NULL)), CONSTRAINT "licenses_started_has_expiry" CHECK ((num_nonnulls(duration_months, duration_seconds) = 0) OR ((expiry_basis)::text <> 'from_first_activation'::text) OR (first_activated_at IS NULL) OR (expires_at IS NOT NULL)), CONSTRAINT "licenses_status_valid" CHECK ((status)::text = ANY (ARRAY['active'::text, 'suspended'::text, 'revoked'::text])), CONSTRAINT "licenses_suspended_at" CHECK (((status)::text = 'suspended'::text) = (suspended_at IS NOT NULL)), CONSTRAINT "licenses_type_valid" CHECK ((type)::text = ANY (ARRAY['dev'::text, 'trial'::text, 'paid'::text, 'community'::text])), CONSTRAINT "licenses_unstarted_no_expiry" CHECK (((expiry_basis)::text <> 'from_first_activation'::text) OR (first_activated_at IS NOT NULL) OR (expires_at IS NULL)));
