-- Create "activations" table
CREATE TABLE "activations" ("id" character varying(40) NOT NULL, "tenant_id" character varying(40) NOT NULL, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "fingerprint" character varying(71) NOT NULL, "fp_source" character varying NOT NULL, "binding" character varying NOT NULL, "mode" character varying NOT NULL, "hostname" character varying(253) NULL, "app_version" character varying(64) NULL, "sdk_version" character varying(64) NULL, "first_seen_at" timestamptz NOT NULL, "last_seen_at" timestamptz NOT NULL, "deactivated_at" timestamptz NULL, "license_id" character varying(40) NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "activations_licenses_activations" FOREIGN KEY ("license_id") REFERENCES "licenses" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "activations_binding" CHECK ((binding)::text = ANY (ARRAY['machine'::text, 'cluster'::text])), CONSTRAINT "activations_deactivated" CHECK ((deactivated_at IS NULL) OR (deactivated_at >= first_seen_at)), CONSTRAINT "activations_fingerprint" CHECK ((fingerprint)::text ~ '^sha256:[0-9a-f]{64}$'::text), CONSTRAINT "activations_id_format" CHECK ((id)::text ~ '^act_[a-z2-7]{26}$'::text), CONSTRAINT "activations_mode" CHECK ((mode)::text = ANY (ARRAY['online'::text, 'offline'::text])), CONSTRAINT "activations_seen_order" CHECK (last_seen_at >= first_seen_at), CONSTRAINT "activations_source" CHECK ((fp_source)::text = ANY (ARRAY['override'::text, 'env'::text, 'kubernetes'::text, 'machine-id'::text])), CONSTRAINT "activations_source_binding" CHECK (((fp_source)::text = 'kubernetes'::text) = ((binding)::text = 'cluster'::text)));
-- Create index "activation_license_id_fingerprint" to table: "activations"
CREATE UNIQUE INDEX "activation_license_id_fingerprint" ON "activations" ("license_id", "fingerprint") WHERE (deactivated_at IS NULL);
